import argparse
from .service import execute

def nonnegative(value):
    try:
        number=int(value)
    except ValueError:
        raise argparse.ArgumentTypeError("invalid integer")
    if number<0:
        raise argparse.ArgumentTypeError("negative limit")
    return number

def main(argv=None):
    parser=argparse.ArgumentParser()
    parser.add_argument("path")
    parser.add_argument("--tenant", default=None)
    parser.add_argument("--limit",type=nonnegative,default=None)
    args=parser.parse_args(argv)
    try:
        output=execute(args.path, tenant=args.tenant, limit=args.limit)
    except ValueError as error:
        parser.error(str(error))
    print(output, end="")

