def select(records, tenant=None, limit=None):
    chosen=[]
    seen=set()
    for row in records:
        if tenant is not None and row["tenant"]!=tenant:
            continue
        key=(row["tenant"], row["id"])
        if key in seen:
            continue
        seen.add(key)
        chosen.append(row)
    return chosen if limit is None else chosen[:limit]
